import { getMetaContent } from "helpers/meta_helpers"

const LOCALE = "en-US"
const MILLISECONDS_PER_DAY = 1000 * 60 * 60 * 24

export function signedDifferenceInDays(fromDate, toDate) {
  return Math.round((beginningOfDay(toDate) - beginningOfDay(fromDate)) / MILLISECONDS_PER_DAY)
}

export function beginningOfDay(date) {
  const { year, month, day } = datePartsInTimezone(date)
  return new Date(Date.UTC(year, month - 1, day))
}

// The viewer's timezone. Prefer the `timezone` meta tag (the timezone the browser
// reported to the server via cookie) so client day boundaries match the server's
// day grouping, which can differ from the resolved timezone in a PWA. Falls back
// to the browser's own timezone.
export function currentTimezone() {
  const timezone = getMetaContent("timezone")
  return isValidTimezone(timezone) ? timezone : browserTimezone()
}

// Formatting

export function formatTime(date) {
  return formatter({ hour: "numeric", minute: "2-digit" }).format(date)
}

// "Sep 12", or "Sep 12, 2024" when not in the current year
export function formatDate(date, now = new Date()) {
  const options = { month: "short", day: "numeric" }
  if (!isSameYear(date, now)) options.year = "numeric"
  return formatter(options).format(date)
}

// "Sep 12, 2025"
export function formatFullDate(date) {
  return formatter({ month: "short", day: "numeric", year: "numeric" }).format(date)
}

// "Thursday, September 12"
export function formatWeekday(date) {
  return formatter({ weekday: "long", month: "long", day: "numeric" }).format(date)
}

// "9/12/25, 1:42 PM"
export function formatDateTime(date) {
  return formatter({ dateStyle: "short", timeStyle: "short" }).format(date)
}

// "Thursday, September 12, 2025 at 1:42 PM"
export function formatLongDateTime(date) {
  return formatter({ dateStyle: "full", timeStyle: "short" }).format(date)
}

// "1:42 PM" today, "yesterday", "5 days ago" within the week, "Sep 12" beyond
export function formatAgo(date, now = new Date()) {
  const days = signedDifferenceInDays(date, now)

  if (days < 1) {
    return formatTime(date)
  } else if (days === 1) {
    return "yesterday"
  } else if (days < 7) {
    return `${days} days ago`
  } else {
    return formatDate(date, now)
  }
}

// "today", "yesterday", "5 days ago", "3 months ago", "2 years ago"
export function formatDaysAgo(date, now = new Date()) {
  const days = signedDifferenceInDays(date, now)

  if (days < 1) {
    return "today"
  } else if (days === 1) {
    return "yesterday"
  } else if (days < 31) {
    return `${days} days ago`
  } else if (days < 365) {
    return pluralize(Math.max(1, Math.round(days / 30.4)), "month", "ago")
  } else {
    return pluralize(Math.floor(days / 365), "year", "ago")
  }
}

// "today", "tomorrow", "in 3 days"
export function formatInDays(date, now = new Date()) {
  const days = signedDifferenceInDays(now, date)

  if (days < 1) {
    return "today"
  } else if (days === 1) {
    return "tomorrow"
  } else {
    return `in ${days} days`
  }
}

function pluralize(count, unit, suffix) {
  return `${count} ${unit}${count === 1 ? "" : "s"} ${suffix}`
}

function isSameYear(date, other) {
  return datePartsInTimezone(date).year === datePartsInTimezone(other).year
}

// Timezone handling

function datePartsInTimezone(date) {
  return formatter({ year: "numeric", month: "2-digit", day: "2-digit" }).formatToParts(date).reduce((parts, { type, value }) => {
    if (type !== "literal") parts[type] = parseInt(value, 10)
    return parts
  }, {})
}

const formatterCache = new Map()

function formatter(options) {
  const timeZone = currentTimezone()
  const key = `${timeZone}|${JSON.stringify(options)}`

  if (!formatterCache.has(key)) {
    formatterCache.set(key, new Intl.DateTimeFormat(LOCALE, { ...options, timeZone }))
  }

  return formatterCache.get(key)
}

const validTimezones = new Map()

function isValidTimezone(timezone) {
  if (!timezone) return false

  if (!validTimezones.has(timezone)) {
    try {
      new Intl.DateTimeFormat(LOCALE, { timeZone: timezone })
      validTimezones.set(timezone, true)
    } catch {
      validTimezones.set(timezone, false)
    }
  }

  return validTimezones.get(timezone)
}

function browserTimezone() {
  return Intl.DateTimeFormat().resolvedOptions().timeZone
}
