module BridgeHelper
  def bridge_icon(name)
    asset_url("#{name}.svg")
  end

  def bridged_button_to_board(board)
    link_to "Go to #{board.name}", board, hidden: true, data: {
      bridge__buttons_target: "button",
      bridge_icon_url: bridge_icon("board"),
      bridge_title: "Go to #{board.name}"
    }
  end

  # The description is rendered as (hidden) content rather than an attribute so
  # it can contain local time tags that the browser formats in the viewer's timezone.
  def bridged_share_url_button(description = nil)
    tag.button hidden: true, data: {
      controller: "bridge--share",
      action: "bridge--share#shareUrl",
      bridge__overflow_menu_target: "item",
      bridge_title: "Share"
    } do
      safe_join [ "Share", (tag.span(description, hidden: true, data: { bridge__share_target: "description" }) if description.present?) ]
    end
  end

  def bridge_share_card_description(card)
    date_added = local_datetime_tag(card.created_at, style: :date)
    date_updated = local_datetime_tag(card.last_active_at, style: :date)
    author = card.creator.familiar_name
    assignees = card.assignees.any? ? "assigned to #{card.assignees.map(&:familiar_name).to_sentence}" : "not assigned"

    safe_join [ "Added ", date_added, " by #{author} and #{assignees}. Updated ", date_updated ]
  end

  def bridge_share_board_description(board)
    count_open = board.cards.active.count
    count_in_stream = board.cards.awaiting_triage.count
    "#{count_open} open cards, #{count_in_stream} in MAYBE?"
  end
end
